// Knowledge Base & Respon Cerdas Frontliner Maya (Ekalaya Laptop Store)
const input = $json.body || $json;
const userMessage = (input.message || '').toLowerCase();
const visitorName = input.clientName || 'Sahabat Ekalaya';
const visitorWA = input.clientWhatsapp || '-';

const catalog = {
  rog: {
    title: 'ROG Titan X Pro',
    price: 'Rp 28.500.000',
    badge: 'Gaming & 3D Render Beast',
    cpu: 'Intel Core i9-14900HX',
    gpu: 'NVIDIA RTX 4080 12GB (175W)',
    display: '16" QHD+ 240Hz 500 nits'
  },
  zenbook: {
    title: 'ZenAir OLED 14',
    price: 'Rp 16.900.000',
    badge: 'Ultra-Slim Executive & AI',
    cpu: 'Intel Core Ultra 7 155H + NPU AI',
    gpu: 'Intel Arc Graphics',
    display: '14" 2.8K 120Hz Lumina OLED, 1.1kg'
  },
  macbook: {
    title: 'MacBook Pro Studio M3 Max',
    price: 'Rp 34.900.000',
    badge: 'Creative Pro Workstation',
    cpu: 'Apple M3 Max 14-Core',
    gpu: '30-Core GPU Metal 3',
    display: '14.2" Liquid Retina XDR 1600 nits'
  },
  swift: {
    title: 'Swift Go 14',
    price: 'Rp 7.800.000',
    badge: 'Best Value & Kuliah',
    cpu: 'AMD Ryzen 5 7530U',
    gpu: 'Radeon Vega Graphics',
    display: '14" FHD+ 100% sRGB, Baterai 12 Jam'
  }
};

let reply = '';
let suggestedId = 'rog';
let isLeadCaptured = false;

// 1. Deteksi Niat / Intent Pengunjung
if (userMessage.includes('gaming') || userMessage.includes('fps') || userMessage.includes('rtx') || userMessage.includes('cyberpunk') || userMessage.includes('game')) {
  suggestedId = 'rog';
  reply = `Halo Kak ${visitorName}! Untuk kebutuhan gaming rata-kanan dan performa grafis tinggi, rekomendasi mutlak saya adalah **ROG Titan X Pro** (Rp 28.500.000). Ditenagai Core i9-14900HX dan RTX 4080 12GB (175W TGP). Cyberpunk 2077 Ultra RTX tembus 98 FPS stabil dengan layar 240Hz. Kakak bisa klik tombol Inspeksi 3D 360° untuk melihat fisik unitnya secara detail!`;
} else if (userMessage.includes('kuliah') || userMessage.includes('mahasiswa') || userMessage.includes('kantor') || userMessage.includes('murah') || userMessage.includes('budget') || userMessage.includes('pelajar')) {
  suggestedId = 'swift';
  reply = `Halo Kak ${visitorName}! Untuk kuliah, tugas skripsi, dan administrasi kantor, **Swift Go 14** (Rp 7.800.000) adalah pilihan paling hemat dan tangguh. RAM 16GB besar anti-lemot, prosesor Ryzen 5 7530U yang adem, dan baterai awet hingga 12 jam. Sudah gratis Windows 11 & Office original seumur hidup!`;
} else if (userMessage.includes('editing') || userMessage.includes('desain') || userMessage.includes('render') || userMessage.includes('video') || userMessage.includes('macbook') || userMessage.includes('oled') || userMessage.includes('kreatif')) {
  suggestedId = 'macbook';
  reply = `Untuk kebutuhan konten kreator dan visual profesional, **MacBook Pro Studio M3 Max** (Rp 34.900.000) adalah juaranya dengan efisiensi render 4K hanya 1.8 menit dan layar XDR 1600 nits. Namun jika mencari laptop Windows yang super tipis dan layarnya OLED memukau, **ZenAir OLED 14** (Rp 16.900.000) dengan bobot cuma 1.1kg juga sangat luar biasa!`;
} else if (userMessage.includes('cicilan') || userMessage.includes('kredit') || userMessage.includes('angsuran') || userMessage.includes('bunga') || userMessage.includes('paylater') || userMessage.includes('kredivo')) {
  suggestedId = 'zenbook';
  reply = `Ekalaya menyediakan fasilitas **Cicilan 0% bebas biaya admin** melalui kartu kredit rekanan (BCA, Mandiri, BNI, BRI) hingga 24 bulan. Simulasi angsuran: Swift Go 14 cuma Rp 325.000/bln, ZenAir OLED Rp 704.000/bln, dan ROG Titan X Rp 1.187.000/bln. Kami juga menerima SpayLater dan Kredivo resmi tanpa kartu kredit!`;
} else if (userMessage.includes('garansi') || userMessage.includes('adp') || userMessage.includes('rusak') || userMessage.includes('air') || userMessage.includes('pecah')) {
  suggestedId = 'rog';
  reply = `Semua unit di Ekalaya bergaransi resmi distributor Indonesia 1-2 tahun. Plus, kami berikan bonus eksklusif **Accidental Damage Protection (ADP) gratis 1 tahun** — menanggung kerusakan akibat ketumpahan air, jatuh, atau lonjakan listrik tanpa biaya tambahan!`;
} else if (userMessage.includes('promo') || userMessage.includes('diskon') || userMessage.includes('voucher') || userMessage.includes('flash sale')) {
  suggestedId = 'rog';
  reply = `Spesial hari ini ada event **Flash Sale Ekalaya** dengan potongan langsung s/d 35%! Gunakan voucher promo kode \`EKALAYASALE500\` saat checkout untuk cashback instan Rp 500.000 + bonus paket ransel, mouse wireless, dan mousepad gaming XXL senilai Rp 1.200.000!`;
} else {
  suggestedId = 'zenbook';
  reply = `Halo Kak ${visitorName}! Saya Maya dari meja Frontliner Ekalaya Laptop Store. Kami menyediakan laptop Gaming RTX bertenaga monster, Ultrabook OLED super tipis 1.1kg, MacBook Pro M3 Max untuk kreator, hingga laptop kuliah mahasiswa. Ada kisaran anggaran atau kebutuhan spesifik yang sedang Kakak rencanakan?`;
}

// Cek jika ada nomor kontak yang masuk
if (visitorWA !== '-' && visitorWA.length > 8) {
  isLeadCaptured = true;
}

return {
  success: true,
  botName: 'Maya (Ekalaya Frontliner AI)',
  reply: reply,
  suggestedLaptop: catalog[suggestedId],
  isLeadCaptured: isLeadCaptured,
  clientName: visitorName,
  clientWhatsapp: visitorWA,
  timestamp: new Date().toISOString()
};

// Format notifikasi instan WhatsApp / Telegram ke Pemilik Toko
const lead = $json;
const pesanWA = `🔥 *LEAD BARU DARI FRONTLINER MAYA 3D*\\n` +
  `Nama: ${lead.clientName}\\n` +
  `WhatsApp: ${lead.clientWhatsapp}\\n` +
  `Minat Unit: ${lead.suggestedLaptop.title} (${lead.suggestedLaptop.price})\\n` +
  `Status: *HOT PROSPECT (Siap Follow-up)*\\n` +
  `Waktu: ${new Date().toLocaleString('id-ID')}\\n` +
  `Catatan: Pengunjung aktif berkonsultasi langsung di showroom virtual.`;

return {
  ...lead,
  ownerNotification: pesanWA,
  channel: 'WhatsApp Sales Team'
};
